mapper.insert:
/* com.heeji.picket.mapper.UserAlarmMapper.insert */
INSERT INTO USER_ALARM (
    SHOW_ID,
    USER_ID,
    INSERT_DATE
) VALUES (
    #{showId},
    #{userId},
    NOW()
)

mapper.delete:
/* com.heeji.picket.mapper.UserAlarmMapper.delete */
DELETE FROM USER_ALARM
WHERE       1 = 1        
AND         SHOW_ID = #{showId}
AND         LIKE_ID = #{likeId}
